{
  "county_id": "HVA19",
  "actions": [
    {
      "action_id": "self-sampling",
      "action": "Mail a self-sampling kit with the second reminder to everyone who has not attended cervical cancer screening.",
      "rationale": "Cervical screening participation in North Ostrobothnia is 73.6% against the 80% target, and the model scenario expects self-sampling kits for non-attenders to add 1.5-4.5 percentage points, closing about 47% of the gap.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of women invited to cervical cancer screening (smear test) who attended, %",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "screening-reminders",
      "action": "Send a second kit with plain-language, multilingual instructions to non-responders to colorectal cancer screening and measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in North Ostrobothnia is 76.9% against the 80% target, and the model scenario expects reminders and multilingual re-invitation to add 1.5-3.13 percentage points, closing about 96% of the gap.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %",
      "roadmap_measure": "1.3.1"
    },
    {
      "action_id": "pathway-timestamps",
      "action": "Add first contact, referral, diagnosis and first treatment dates, plus entry route, to the national cancer quality register and publish county-level medians quarterly.",
      "rationale": "North Ostrobothnia is clearly worse than the country at first contact and primary care access, with 8.23% of primary care appointments waiting over 3 months and 81.07 patients per 10 000 waiting over 6 months for specialised care, and the time from referral to diagnosis and from diagnosis to first treatment is not published by county for any cancer.",
      "owner_role": "FICAN with THL and the Finnish Cancer Registry",
      "indicator": "Share of new cancer cases with all four timestamps recorded",
      "roadmap_measure": "3.2.1"
    }
  ],
  "evidence_does_not_support": "The evidence does not support a Finnish effect size for colorectal screening reminders, as the gain is borrowed from cervical screening and must be measured, and the roadmap does not name HPV self-sampling kits, a second colorectal screening kit, or quarterly publication of county-level medians."
}

